import React, { useState } from 'react';
import { Menu, X, User } from 'lucide-react';

interface NavbarProps {
  onNavigate: (page: string) => void;
  currentPage: string;
  isAdmin: boolean;
}

const AlmaLogo = ({ className }: { className?: string }) => (
  <svg viewBox="0 0 500 500" className={className} xmlns="http://www.w3.org/2000/svg">
    <defs>
      {/* Path for the bottom text to follow the curve of the ring */}
      <path id="ringPath" d="M 100, 260 A 160, 160 0 0, 0 400, 260" fill="none" />
    </defs>

    {/* Main Orange Circle */}
    <circle cx="250" cy="250" r="190" stroke="#FF6600" strokeWidth="50" fill="none" />

    {/* V Shape (Chevron) - Integrated nicely */}
    <path d="M 50 30 L 250 250 L 450 30" stroke="#FF6600" strokeWidth="60" fill="none" strokeLinecap="butt" strokeLinejoin="miter" />

    {/* Text VISEU */}
    <text x="250" y="380" textAnchor="middle" fill="#FF6600" fontSize="80" fontWeight="900" fontFamily="Arial, sans-serif" letterSpacing="4">VISEU</text>

    {/* Curved Text FUNDADO EM 2022 (White text on the orange ring) */}
    <text fill="white" fontSize="32" fontWeight="bold" letterSpacing="2" fontFamily="Arial, sans-serif">
      <textPath href="#ringPath" startOffset="50%" textAnchor="middle">
        FUNDADO EM 2022
      </textPath>
    </text>
  </svg>
);

export const Navbar: React.FC<NavbarProps> = ({ onNavigate, currentPage, isAdmin }) => {
