      {currentPage !== 'admin' && currentPage !== 'login' && <Navbar onNavigate={setCurrentPage} currentPage={currentPage} isAdmin={!!session} />}
      <main className="flex-grow">
        {renderContent()}
      </main>
      {currentPage !== 'admin' && currentPage !== 'login' && <Footer />}
    </div>
  );
}

