  score_home?: number;
  score_guest?: number;
  category: string;
}

export interface Product {
  id: string;
  name: string;
  price: number;
  description: string;
  image_url: string;
}

export interface Partner {
  id: string;
  name: string;
  website_url: string;
  logo_url: string;
}

export interface Team {
  id: string;
  name: string;
  category: string; // e.g., Séniores Masculinos, Iniciados
  description: string;
  image_url: string;
}

export interface GalleryItem {
