-- 1. Criar a tabela para conteúdo dinâmico (Hero/Início)
create table if not exists site_content (
  id uuid default gen_random_uuid() primary key,
  section text unique,
  title text,
  subtitle text,
  image_url text
);

-- 2. Habilitar a segurança (RLS)
alter table site_content enable row level security;

-- 3. Criar políticas de acesso

-- Remover políticas antigas se existirem (para evitar erros ao re-executar)
drop policy if exists "Public read site_content" on site_content;
drop policy if exists "Auth all site_content" on site_content;

-- Permitir leitura pública (para o site mostrar o conteúdo)
create policy "Public read site_content" on site_content for select using (true);

-- Permitir gestão total apenas para utilizadores autenticados (Admin)
create policy "Auth all site_content" on site_content for all using (auth.role() = 'authenticated');

-- 4. Inserir dados padrão (para a secção não ficar vazia inicialmente)
