      {subtitle && (
        <div className="text-inherit opacity-70 max-w-2xl mx-auto" dangerouslySetInnerHTML={{ __html: subtitle }}></div>
      )}
      <div className="w-24 h-1 bg-primary mx-auto mt-4"></div>
    </div>
  );
};

