      formattedItems = items.map((i: Product) => ({
        id: i.id,
        image: i.image_url || `https://picsum.photos/seed/${i.id}/800/600`,
        title: i.name,
        subtitle: `${i.price.toFixed(2)} €`,
        description: i.description
