              <button onClick={() => setAdminTab('conteudo')} className={`w-full text-left p-2 rounded capitalize font-medium ${adminTab === 'conteudo' ? 'bg-primary text-white' : 'hover:bg-neutral-100 text-neutral-700'}`}>
