                <label className="block text-sm font-bold text-neutral-600 mb-1">
                  {selectedSection === 'branding' ? 'Imagem do Logótipo' : 'Imagem de Fundo'}
                </label>
                <input type="file" accept="image/*" onChange={(e) => {
                  if (e.target.files?.[0]) {
