        title: i.name,
        subtitle: `${i.price.toFixed(2)} €`,
        description: i.description
      }));
    } else if (type === 'team') {
      formattedItems = items.map((i: Team) => {
        const roster = teamMembers.filter(m => m.team_id === i.id);
        return {
          id: i.id,
          image: i.image_url || `https://picsum.photos/seed/${i.id}/800/600`,
          title: i.name,
          subtitle: i.category,
          description: i.description,
