              {gallery.map((g, index) => (
                <div 
                  key={g.id} 
                  className="relative group overflow-hidden aspect-square cursor-pointer snap-center min-w-[200px] md:min-w-[300px] rounded-lg"
                  onClick={() => openModal(gallery, index, 'gallery')}
