            </SectionCarousel>
        </DynamicSection>
      </section>

      {/* PARTNERS SECTION */}
      <DynamicSection id="partners" content={siteContent['partners']} defaultClass="bg-neutral-100 text-black" defaultTitle="Os Nossos Parceiros" padding="py-6">
          <PartnersMarquee partners={partners} />
