                   <p className="text-neutral-500 text-sm">Acesso exclusivo a administradores</p>
                </div>

                {loginError && <div className="bg-red-500/10 border border-red-500/50 text-red-500 p-3 rounded mb-4 text-sm flex items-center gap-2"><AlertTriangle size={16}/> {loginError}</div>}

                <form onSubmit={handleAuth} className="space-y-4">
                  <div>
                    <label className="block text-xs font-bold uppercase text-neutral-500 mb-1">Email</label>
                    <div className="relative">
                      <input type="text" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-black border border-neutral-700 p-3 pl-10 rounded text-white focus:border-primary outline-none transition" placeholder="admin" />
