                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase text-neutral-500 mb-1">Password</label>
                    <div className="relative">
                       <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-black border border-neutral-700 p-3 pl-10 rounded text-white focus:border-primary outline-none transition" placeholder="••••••" />
                       <Lock size={16} className="absolute left-3 top-3.5 text-neutral-600" />
                    </div>
                  </div>
                  <button className="w-full bg-primary text-white font-bold py-3 rounded hover:bg-orange-700 transition uppercase tracking-widest text-sm flex items-center justify-center gap-2">
                    <LogIn size={16} /> Entrar
                  </button>
                </form>
              </div>
            </div>
          );
       }
       return renderAdmin();
    }

    if (currentPage === 'about') {
       return (
        <div className="min-h-screen bg-black text-white font-sans selection:bg-primary selection:text-white">
          <Navbar onNavigate={setCurrentPage} currentPage={currentPage} isAdmin={!!session} logoUrl={siteContent['branding']?.image_url} />
          <AboutPage teams={teams} organization={organization} />
          <Footer content={siteContent['footer']} onNavigate={setCurrentPage} />
        </div>
       );
    }

    if (currentPage === 'contacts') {
       return (
        <div className="min-h-screen bg-black text-white font-sans selection:bg-primary selection:text-white">
          <Navbar onNavigate={setCurrentPage} currentPage={currentPage} isAdmin={!!session} logoUrl={siteContent['branding']?.image_url} />
          <ContactsPage content={siteContent['contacts']} />
          <Footer content={siteContent['footer']} onNavigate={setCurrentPage} />
        </div>
       );
    }

    // Default: Home
    return (
        <div className="min-h-screen bg-black text-white font-sans selection:bg-primary selection:text-white">
          <Navbar onNavigate={setCurrentPage} currentPage={currentPage} isAdmin={!!session} logoUrl={siteContent['branding']?.image_url} />
