      formattedItems = items.map((i: Team) => {
        const roster = teamMembers ? teamMembers.filter(m => m.team_id === i.id) : [];
        return {
          id: i.id,
          image: i.image_url || `https://picsum.photos/seed/${i.id}/800/600`,
          title: i.name,
          subtitle: undefined, // Removed category
