           </div>
        </div>
      </div>
      <div 
        ref={editorRef}
        className="p-4 min-h-[150px] outline-none max-h-[500px] overflow-y-auto leading-normal"
        contentEditable
        onInput={handleInput}
        onBlur={handleInput}
