        </div>
      )}
      <div className="relative z-10 max-w-7xl mx-auto">
        {(title) && (
           <SectionTitle title={title} subtitle={subtitle} className={!bgImage && defaultClass.includes('text-black') ? 'text-black' : 'text-white'} />
