const LandingPage = ({ 
  onNavigate, 
  news, 
  matches, 
  products, 
  partners, 
  teams, 
  teamMembers,
  gallery,
  heroContent, 
  siteContent
}: { 
  onNavigate: (p: string) => void, 
  news: NewsItem[], 
  matches: Match[], 
  products: Product[],
  partners: Partner[],
  teams: Team[],
  teamMembers: TeamMember[],
  gallery: GalleryItem[],
  organization?: OrganizationMember[],
  heroContent: SiteContent | null,
  siteContent: Record<string, SiteContent>
